//! Check 3: every generated file is registered against the command that writes it and carries that
//! command's exact header (`docs/PHASE1.md` §3, §6). The regeneration comparison is each generator's
//! own check (`thresholds --check`, `just atan-fit-check`); this check owns the registry and the
//! header. A file claims to be generated when one of its first three lines is a comment leader
//! followed by the marker, the shape `header_command` parses; prose that mentions the marker, and
//! another tool's `Cargo.lock` at any depth (its marker is mid-sentence), are not claims.

use super::{File, Violation};

/// `(path, the command that writes it)`: a `cargo xtask` task, or a `just` recipe for a generator
/// that is not Rust. A generator adds its output here in the PR that adds the generator.
const REGISTRY: &[(&str, &str)] = &[
    ("xtask/src/seeded/generated.rs", "cargo xtask thresholds"),
    (
        "crates/helicoid/src/coeffs/generated.rs",
        "cargo xtask thresholds",
    ),
    (
        "crates/helicoid/src/coeffs/generated_sim3.rs",
        "cargo xtask thresholds",
    ),
    (
        "crates/helicoid-linalg/src/math/generated.rs",
        "just atan-fit",
    ),
    ("docs/evidence/ENVELOPE.md", "cargo xtask envelope"),
    ("baseline/HOST.md", "cargo xtask bench-gate"),
];

pub(crate) fn check_registry(files: &[File]) -> Vec<Violation> {
    check(files, REGISTRY)
}

/// One valid file per registry entry, the header its task writes and nothing else: the fixtures of
/// the other checks add them so that the registry, which they do not test, stays silent.
#[cfg(test)]
pub(super) fn stubs() -> Vec<File> {
    let header = |command: &str| format!("// @generated by `{command}` — do not edit.\n");
    let stub = |&(path, command): &(&str, &str)| File::new(path, &header(command));
    REGISTRY.iter().map(stub).collect()
}

fn check(files: &[File], registry: &[(&str, &str)]) -> Vec<Violation> {
    let mut out = Vec::new();
    for f in files {
        let claimed = f
            .text
            .lines()
            .take(3)
            .position(|l| strip_leader(l).starts_with("@generated"));
        let owner = registry.iter().find(|(p, _)| *p == f.path).map(|&(_, t)| t);
        match (owner, claimed) {
            (Some(command), _) if header_command(&f.text) != Some(command) => {
                out.push(Violation::new(
                    &f.path,
                    1,
                    format!("[generated] must start with `@generated by `{command}``"),
                ));
            }
            (None, Some(n)) => out.push(Violation::new(
                &f.path,
                n + 1,
                "[generated] `@generated` file is not in the xtask registry; register it with its command",
            )),
            _ => {}
        }
    }
    for (path, command) in registry {
        if !files.iter().any(|f| f.path == *path) {
            out.push(Violation::new(
                path,
                1,
                format!("[generated] registered output of `{command}` does not exist"),
            ));
        }
    }
    out
}

fn strip_leader(line: &str) -> &str {
    line.trim_start_matches(|c: char| c.is_whitespace() || "/!#*<-".contains(c))
}

/// The command named by a first line of the form: comment leader, marker, ``cargo xtask TASK``
/// or ``just RECIPE``.
fn header_command(text: &str) -> Option<&str> {
    let rest = strip_leader(text.lines().next()?).strip_prefix("@generated by `")?;
    let (command, _) = rest.split_once('`')?;
    let name = command
        .strip_prefix("cargo xtask ")
        .or_else(|| command.strip_prefix("just "))?;
    (!name.is_empty() && !name.contains(' ')).then_some(command)
}

#[cfg(test)]
mod tests {
    use super::*;

    const REG: &[(&str, &str)] = &[
        ("crates/x/gen.rs", "cargo xtask thresholds"),
        ("crates/x/fit.rs", "just fit"),
    ];
    const HDR: &str =
        "// @generated by `cargo xtask thresholds` from a.csv — do not edit.\nfn f() {}\n";

    fn run(files: &[File]) -> Vec<String> {
        let fit = File::new("crates/x/fit.rs", "// @generated by `just fit` from a.py\n");
        let copy = files.iter().map(|f| File::new(&f.path, &f.text));
        let files: Vec<File> = copy.chain([fit]).collect();
        check(&files, REG).iter().map(ToString::to_string).collect()
    }

    #[test]
    fn registered_file_with_header_passes() {
        assert!(run(&[File::new("crates/x/gen.rs", HDR)]).is_empty());
        let md = "<!-- @generated by `cargo xtask thresholds` -->\n";
        assert!(run(&[File::new("crates/x/gen.rs", md)]).is_empty());
        for lead in ["# ", "/* ", " * ", "//! ", "-- "] {
            let text = format!("{lead}@generated by `cargo xtask thresholds`\n");
            assert!(
                run(&[File::new("crates/x/gen.rs", &text)]).is_empty(),
                "{lead}"
            );
        }
    }

    #[test]
    fn registered_file_with_wrong_or_missing_header_fails() {
        for text in [
            "// header dropped\n",
            "\n// @generated by `cargo xtask thresholds`\n",
            "// @generated by `cargo xtask envelope`\n",
            "// @generated by cargo xtask thresholds\n",
            "// @generated by `cargo xtask `\n",
            "// @generated by `just thresholds`\n",
            "// @generated by `make thresholds`\n",
        ] {
            let v = run(&[File::new("crates/x/gen.rs", text)]);
            assert_eq!(v.len(), 1, "{text:?} -> {v:?}");
            assert!(v[0].starts_with("crates/x/gen.rs:1: "), "{v:?}");
        }
    }

    #[test]
    fn the_registry_names_the_generated_files_and_their_tasks() {
        assert_eq!(
            REGISTRY,
            [
                ("xtask/src/seeded/generated.rs", "cargo xtask thresholds"),
                (
                    "crates/helicoid/src/coeffs/generated.rs",
                    "cargo xtask thresholds"
                ),
                (
                    "crates/helicoid/src/coeffs/generated_sim3.rs",
                    "cargo xtask thresholds"
                ),
                (
                    "crates/helicoid-linalg/src/math/generated.rs",
                    "just atan-fit"
                ),
                ("docs/evidence/ENVELOPE.md", "cargo xtask envelope"),
                ("baseline/HOST.md", "cargo xtask bench-gate"),
            ]
        );
        // The header the generator writes, from its first line, is the one the check parses.
        let header = |csv: &str| {
            format!("// @generated by `cargo xtask thresholds` from {csv} — do not edit.\n")
        };
        let files = [
            File::new(
                REGISTRY[0].0,
                &header("conformance/sweeps/thresholds-seeded.csv"),
            ),
            File::new(REGISTRY[1].0, &header("conformance/sweeps/thresholds.csv")),
        ];
        // Only the two `thresholds` files are present, so every other entry is reported.
        assert_eq!(check_registry(&files).len(), REGISTRY.len() - files.len());
        assert_eq!(check_registry(&stubs()).len(), 0);
        assert_eq!(check_registry(&[]).len(), REGISTRY.len());
    }

    #[test]
    fn missing_registered_file_fails() {
        assert_eq!(run(&[]).len(), 1);
    }

    /// A `just` recipe's header is the registered command's, and only that command's.
    #[test]
    fn a_just_recipe_is_a_command() {
        let reg = &[("crates/x/fit.rs", "just fit")];
        let ok = File::new("crates/x/fit.rs", "// @generated by `just fit` from a.py\n");
        assert!(check(&[ok], reg).is_empty());
        let other = File::new("crates/x/fit.rs", "// @generated by `just fit-check`\n");
        assert_eq!(check(&[other], reg).len(), 1);
    }

    #[test]
    fn unregistered_generated_file_fails_within_three_lines_only() {
        let v = check(&[File::new("docs/E.md", "a\n\n<!-- @generated -->\n")], &[]);
        assert_eq!(v.len(), 1);
        assert!(v[0].to_string().starts_with("docs/E.md:3: "), "{v:?}");
        let late = File::new("docs/E.md", "a\nb\nc\n@generated\n");
        assert!(check(&[late], &[]).is_empty());
    }

    #[test]
    fn foreign_and_prose_mentions_are_not_claims() {
        let lock = "# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\n";
        for path in ["Cargo.lock", "runners/nalgebra/Cargo.lock"] {
            assert!(check(&[File::new(path, lock)], &[]).is_empty(), "{path}");
        }
        let prose = File::new("docs/N.md", "# Notes on the @generated marker\n");
        assert!(check(&[prose], &[]).is_empty());
    }
}
